-- Catalogue fingerprint items (kind, name, h). Read-only catalogue SELECT only; runs unchanged on staging (PG17) and on the local replica (PG16).
-- h is md5 of the object definition text as rendered by the server. MAINTAIN ('m') privileges are excluded (PG17-only).
select 'enum' as kind, t.typname::text as name, md5(string_agg(e.enumlabel, ',' order by e.enumsortorder)) as h from pg_type t join pg_enum e on e.enumtypid=t.oid where t.typnamespace='public'::regnamespace group by t.typname
union all select 'column', c.relname||'.'||a.attname, md5(format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull::text||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'')||'|'||a.attidentity::text||'|'||a.attgenerated::text) from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where c.relnamespace='public'::regnamespace and c.relkind in ('r','v') and a.attnum>0 and not a.attisdropped
union all select 'table_flags', c.relname, md5(c.relrowsecurity::text||c.relforcerowsecurity::text||coalesce(c.reloptions::text,'')||c.relkind::text) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','S')
union all select 'constraint', c.relname||'.'||k.conname, md5(pg_get_constraintdef(k.oid)) from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace='public'::regnamespace
union all select 'index', indexname::text, md5(indexdef) from pg_indexes where schemaname='public'
union all select 'trigger', c.relname||'.'||t.tgname, md5(pg_get_triggerdef(t.oid)) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace in ('public'::regnamespace,'auth'::regnamespace)
union all select 'policy', schemaname||'.'||tablename||'.'||policyname, md5(cmd::text||'|'||permissive::text||'|'||roles::text||'|'||coalesce(qual,'')||'|'||coalesce(with_check,'')) from pg_policies where schemaname in ('public','storage')
union all select 'function_body', p.oid::regprocedure::text, md5(p.prosrc||'|'||p.prosecdef::text||'|'||p.provolatile::text||'|'||coalesce(p.proconfig::text,'')||'|'||p.prorettype::regtype::text||'|'||p.proretset::text||'|'||pg_get_function_arguments(p.oid)) from pg_proc p where p.pronamespace='public'::regnamespace
union all select 'function_acl', p.oid::regprocedure::text, md5(coalesce((select string_agg(coalesce(g.grantee::regrole::text,'PUBLIC')||':'||g.privilege_type, ',' order by g.grantee, g.privilege_type) from aclexplode(p.proacl) g),'NULL')) from pg_proc p where p.pronamespace='public'::regnamespace
union all select 'relation_acl', c.relname, md5(coalesce((select string_agg(coalesce(g.grantee::regrole::text,'PUBLIC')||':'||g.privilege_type, ',' order by g.grantee, g.privilege_type) from aclexplode(c.relacl) g where g.privilege_type<>'MAINTAIN'),'NULL')) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','S')
union all select 'view_def', c.relname, md5(pg_get_viewdef(c.oid,false)) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v'
union all select 'sequence', sequencename::text, md5(data_type::text||start_value::text||increment_by::text||min_value::text||max_value::text||cycle::text||cache_size::text) from pg_sequences where schemaname='public'
union all select 'bucket', id::text, md5(public::text||coalesce(file_size_limit::text,'')||coalesce(allowed_mime_types::text,'')) from storage.buckets
